window.marchStdlib = window.marchStdlib || {};
window.marchStdlib["authority.march"] = "-- Authority: refusals of capability operations as values.\n--\n-- Every capability operation returns `Result(T, CapError)`\n-- (specs/2026-11-10-object-capability-design.md \u00a715). The types live in the\n-- Prelude so `CapError` and its constructors are bare names everywhere:\n--\n--   type CapLimit = ByLaunch | ByFnNeeds(String) | ByModNeeds(String)\n--                 | ByRestrict(String) | ByGrant(String) | ByMock(Int)\n--   type CapError = CapError(kind, target, limit, limit_scope)\n--\n-- `kind` is the capability (`IO.FileRead`), `target` what the operation\n-- named (a path, `host:port`, a variable name; `\"\"` when it names nothing),\n-- `limit` which limit refused it and `limit_scope` that limit's scope list\n-- as written. Phase 1 produces only `ByLaunch`; the others arrive with\n-- run-time authority, `restrict` and dependency grants.\n--\n-- This module performs no operation of its own and has no `needs` line.\n\nmod Authority do\n\n  -- The run-time authority (ocap phase 4, specs/plans/2026-11-15-ocap-p4-\n  -- runtime-plan.md). The current authority is a stack of layers, innermost\n  -- first, held in the running green thread's slot (the builtins `cap_save`,\n  -- `cap_push`, `cap_enter`, `cap_restore`), else the launch layers\n  -- (`cap_set_launch`); `cap_layers()` reads whichever is in force. A layer\n  -- is the limit that set it, that limit's scope list as written, and the\n  -- list parsed once into scopes. `Any` admits every target of its kind.\n  --\n  -- The C runtime releases a dropped slot value structurally\n  -- (march_cap_release in runtime/march_runtime.c walks exactly these\n  -- shapes): change a constructor here and change it there.  Constructors\n  -- are only ever APPENDED: the C walk reads them by tag.\n  --\n  -- `HostAt(spec, host, wildcard, port)` is what `parse` makes of a host\n  -- scope: the packed spec (as `Hosts` holds it, for `subset` and for\n  -- writing the scope back), and its pattern decoded once, so a check\n  -- compares instead of re-parsing.  `host` is \"\" when the spec names no\n  -- host (`IO.NetConnect(no_redirects)`): any host is admitted.\n  -- `PathsAt(paths)` is what `parse` makes of a path scope: the paths\n  -- normalized once (absolute, no `.`/`..`/empty segment, no trailing `/`),\n  -- so a check compares the normalized target with each path as a string\n  -- instead of splitting the path.  `Hosts` and `Paths` stay for values\n  -- built by hand (a `Paths` entry need not be normalized).\n  type Arg = Any | Paths(List(String)) | Hosts(String) | Names(List(String), List(String))\n           | HostAt(String, String, Bool, Int) | PathsAt(List(String))\n  type CapEntry = CapEntry(String, Arg)\n  type Layer = Layer(CapLimit, String, List(CapEntry))\n\n  doc \"\"\"\n  A one-line description of a refusal: the refused operation written as a\n  scope, the limit that refused it, and that limit's scope list.\n\n  ## Examples\n\n      march> Authority.describe(CapError(\"IO.Clock\", \"\", ByModNeeds(\"Report\"), \"IO.Console\"))\n      \"IO.Clock refused by module Report's needs (IO.Console)\"\n  \"\"\"\n  fn describe(e : CapError) : String do\n    match e do\n    CapError(kind, target, limit, scope) ->\n      let o_pre = if target == \"\" do kind else kind ++ \"(\\\"\" ++ target ++ \"\\\")\" end\n      let who = limit_text(limit)\n      let allowed = if scope == \"\" do \"nothing\" else scope end\n      o_pre ++ \" refused by \" ++ who ++ \" (\" ++ allowed ++ \")\"\n    end\n  end\n\n  pfn limit_text(limit : CapLimit) : String do\n    match limit do\n    ByLaunch      -> \"the launch grant\"\n    ByFnNeeds(f)  -> \"function \" ++ f ++ \"'s needs\"\n    ByModNeeds(m) -> \"module \" ++ m ++ \"'s needs\"\n    ByRestrict(w) -> \"the restrict at \" ++ w\n    ByGrant(p)    -> \"the grant to package \" ++ p\n    ByMock(_)     -> \"a mock\"\n    end\n  end\n\n  impl Show(CapError) do\n    fn show(e : CapError) : String do\n      describe(e)\n    end\n  end\n\n  doc \"\"\"\n  The `Ok` payload of a capability operation's result; a refusal panics\n  with `describe` of the error. What `forge fix` writes where a program used\n  an operation's value before operations could be refused.\n\n  ## Examples\n\n      march> Authority.must(Ok(3))\n      3\n  \"\"\"\n  fn must(r : Result(a, CapError)) : a do\n    match r do\n    Ok(v)  -> v\n    Err(e) -> panic(\"capability refused: \" ++ describe(e))\n    end\n  end\n\n  doc \"\"\"\n  Discards a capability operation's result, refused or not. What `forge\n  fix` writes where a program used an operation such as `println` only for\n  its effect, in a position that needs `()`.\n\n  ## Examples\n\n      march> Authority.ignore(Ok(1))\n      ()\n  \"\"\"\n  fn ignore(_r : Result(a, CapError)) : () do\n    ()\n  end\n\n  doc \"\"\"\n  `Ok(())` when the current authority admits an operation of capability\n  `kind` on `target`, else `Err(CapError(...))` naming the limit that\n  refused it. Every stdlib entry point that performs a capability operation\n  calls this first.\n\n  With no launch scopes, no narrowed launch and no frame ever entered, the\n  runtime answers at once and none of the policy below runs.\n\n  ## Examples\n\n      march> Authority.check(\"IO.Console\", \"stdout\")\n      Ok(())\n  \"\"\"\n  fn check(kind : String, target : String) : Result((), CapError) do\n    let r = cap_check_raw(kind, target)\n    if r == 0 do Ok(()) else check_slow(kind, target, r) end\n  end\n\n  -- `check` once the runtime has not answered at once (`r` is 1: the\n  -- current layers decide; `r` is kept for the C twin's signature).  A\n  -- native or JIT program calls the C runtime's copy of this and of\n  -- `parse`, `admits`, `subset`, `frame_layer`, `launch_init` and\n  -- `check_layers` instead (runtime/march_authority.c, retargeted by\n  -- lib/tir/auth_native.ml), so it links none of the policy below; the\n  -- interpreter and JS run it.\n  pfn check_slow(kind : String, target : String, _r : Int) : Result((), CapError) do\n    check_layers(kind, target, cap_layers())\n  end\n\n  doc \"\"\"\n  The layered check behind `check`: `Err(CapError(kind, target, limit,\n  text))` for the first layer (innermost first) whose scopes do not admit\n  `(kind, target)`, else `Ok(())`. A relative path target is resolved\n  against the current directory (and refused when that cannot be read).\n\n  ## Examples\n\n      march> Authority.check_layers(\"IO.Clock\", \"\", [Authority.Layer(ByFnNeeds(\"f\"), \"IO.Console\", [Authority.CapEntry(\"IO.Console\", Authority.Any)])])\n      Err(CapError(\"IO.Clock\", \"\", ByFnNeeds(\"f\"), \"IO.Console\"))\n  \"\"\"\n  fn check_layers(kind : String, target : String, layers : List(Layer)) : Result((), CapError) do\n    let cwd = if path_kind(kind) && not(string_starts_with(target, \"/\")) do cap_cwd() else \"/\" end\n    first_refusal(kind, kind_chain(kind), target, cwd, layers)\n  end\n\n  -- `chain` is `kind_chain(kind)`, walked once per check, not per scope.\n  pfn first_refusal(kind : String, chain : List(String), target : String, cwd : String, layers : List(Layer)) : Result((), CapError) do\n    match layers do\n    Nil -> Ok(())\n    Cons(Layer(ByMock(_), _, scopes), rest) ->\n      -- A mock (ocap phase 7) never refuses. One that covers the operation\n      -- admits it whatever the layers outside it say: a test may mock what\n      -- it was not launched with (design \u00a712). Layers inside it still apply.\n      if mock_covers(scopes, kind, target, cwd) do Ok(()) else first_refusal(kind, chain, target, cwd, rest) end\n    Cons(Layer(limit, text, scopes), rest) ->\n      if admits_in(scopes, chain, kind, target, cwd) do first_refusal(kind, chain, target, cwd, rest)\n      else Err(CapError(kind, target, limit, text)) end\n    end\n  end\n\n  -- \u2500\u2500 Launch and frames (called by compiler-generated code) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Sets the launch authority before any module-level code runs. `request`\n  is `main`'s request as a scope list; `scoped` whether it carries a scope.\n  An unscoped request with `MARCH_GRANT` unset sets nothing, so the runtime\n  keeps its fast path. A malformed `MARCH_GRANT`, or one granting what\n  `main` does not request, prints one line to stderr and exits with status 2.\n  \"\"\"\n  @[stdlib_internal]\n  fn launch_init(request : String, scoped : Bool) : () do\n    let grant = cap_grant_text()\n    if not(scoped) && grant == \"\" do ()\n    else\n      match parse(request) do\n      Err(e) -> panic(\"internal: main's request is not a scope list: \" ++ e)\n      Ok(req) ->\n        if grant == \"\" do cap_set_launch([Layer(ByLaunch, request, req)])\n        else\n          match parse(grant) do\n          Err(e) -> launch_error(\"march: MARCH_GRANT is not a scope list: \" ++ e)\n          Ok(g) ->\n            match first_outside(g, req) do\n            Some(s) ->\n              launch_error(\"march: MARCH_GRANT grants \" ++ scope_text(s)\n                ++ \", which main does not request (main requests: \" ++ request ++ \")\")\n            None -> cap_set_launch([Layer(ByLaunch, grant, g)])\n            end\n          end\n        end\n      end\n    end\n  end\n\n  -- One line on fd 2, then exit status 2 (cap_launch_fail: an internal\n  -- builtin, so the launch code links neither print_stderr nor\n  -- process_exit, which would attribute IO.Console / IO.Process to every\n  -- binary).\n  pfn launch_error(msg : String) : () do\n    cap_launch_fail(msg ++ \"\\n\")\n  end\n\n  -- The first entry of `a` that no entry of `b` covers.\n  pfn first_outside(a : List(CapEntry), b : List(CapEntry)) : Option(CapEntry) do\n    match a do\n    Nil -> None\n    Cons(s, rest) -> if covered(s, b) do first_outside(rest, b) else Some(s) end\n    end\n  end\n\n  doc \"\"\"\n  The layer of function `name`'s frame, whose `needs` clause is\n  `needs_text`: the clause parsed into scopes. The compiler calls it once\n  per framed function and keeps the result (lib/tir/auth_rt.ml); the\n  interpreter once per definition.\n\n  ## Examples\n\n      march> Authority.frame_layer(\"f\", \"IO.Console\")\n      Layer(ByFnNeeds(\"f\"), \"IO.Console\", [CapEntry(\"IO.Console\", Any)])\n  \"\"\"\n  fn frame_layer(name : String, needs_text : String) : Layer do\n    match parse(needs_text) do\n    Ok(scopes) -> Layer(ByFnNeeds(name), needs_text, scopes)\n    Err(e) -> panic(\"internal: the needs clause of \" ++ name ++ \" is not a scope list: \" ++ e)\n    end\n  end\n\n  doc \"\"\"\n  Enters a function's frame (`layer`, from `frame_layer`) and returns the\n  authority to restore on leaving it. A frame already in force (the top\n  layer has the same limit and scope text) is not pushed again: two string\n  comparisons, no parsing.\n  \"\"\"\n  @[stdlib_internal]\n  -- The result is a CapAuthRef (the builtins' opaque type, which has no\n  -- declaration to name in an annotation).\n  fn enter_fn(layer : Layer) do\n    if top_is_frame(cap_layers(), layer) do\n      -- Entering the authority in force changes nothing, and what comes\n      -- back holds no reference to it, so a panic that skips the restore\n      -- leaves nothing behind (a bare `cap_save()` here would).\n      let cur = cap_save()\n      cap_enter(cur)\n    else cap_push(layer) end\n  end\n\n  pfn top_is_frame(layers : List(Layer), layer : Layer) : Bool do\n    match layers do\n    Cons(Layer(l, t, _), _) ->\n      match layer do\n      Layer(limit, text, _) -> l == limit && t == text\n      end\n    _ -> false\n    end\n  end\n  -- (a restrict's limit and text identify its frame as a function's do)\n\n  -- \u2500\u2500 Matching \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  doc \"\"\"\n  Whether a scope list admits an operation of capability `kind` on\n  `target`. An entry admits when its capability is `kind` or a lattice\n  ancestor of it, and it is unscoped, or `kind` takes its kind of scope and\n  `target` matches: a path (a relative one resolved against `cwd`, then\n  compared by whole segments; refused when `cwd` is `\"\"`, unknown), a\n  `host:port`, or a name. A host scope also admits the host-neutral\n  operations (target `\"\"`) of the capabilities under `IO.NetConnect`, such\n  as building a TLS context: the connections they serve are still bounded\n  by the scope.\n\n  ## Examples\n\n      march> Authority.admits([Authority.CapEntry(\"IO.FileSystem\", Authority.Paths([\"/srv\"]))], \"IO.FileRead\", \"/srv/x\", \"/\")\n      true\n      march> Authority.admits([Authority.CapEntry(\"IO.FileSystem\", Authority.Paths([\"/srv\"]))], \"IO.FileRead\", \"/srvx\", \"/\")\n      false\n  \"\"\"\n  fn admits(scopes : List(CapEntry), kind : String, target : String, cwd : String) : Bool do\n    admits_in(scopes, kind_chain(kind), kind, target, cwd)\n  end\n\n  -- An entry's capability subsumes `kind` when it is in `chain`\n  -- (`kind_chain(kind)`): a membership test per entry instead of a lattice\n  -- walk per entry.\n  pfn admits_in(scopes : List(CapEntry), chain : List(String), kind : String, target : String, cwd : String) : Bool do\n    match scopes do\n    Nil -> false\n    Cons(CapEntry(k, arg), rest) ->\n      (member(chain, k) && arg_admits(arg, kind, target, cwd))\n        || admits_in(rest, chain, kind, target, cwd)\n    end\n  end\n\n  pfn arg_admits(arg : Arg, kind : String, target : String, cwd : String) : Bool do\n    match arg do\n    Any -> true\n    Paths(ps) ->\n      if not(path_kind(kind)) do false\n      else if cwd == \"\" && not(string_starts_with(target, \"/\")) do false\n      else any_within(ps, resolve(cwd, target)) end end\n    Hosts(spec) -> if host_kind(kind) do host_permits(spec, target) else target == \"\" end\n    Names(ns, pre) -> name_kind(kind) && name_admits(ns, pre, target)\n    HostAt(_, h, wild, port) ->\n      if host_kind(kind) do\n        if h == \"\" do true\n        else\n          match split_target(target) do\n          (th, tp) -> host_matches(h, wild, port, th, tp)\n          end\n        end\n      else target == \"\" end\n    PathsAt(ps) ->\n      if not(path_kind(kind)) do false\n      else if cwd == \"\" && not(string_starts_with(target, \"/\")) do false\n      else any_normal_within(ps, normalize(resolve(cwd, target))) end end\n    end\n  end\n\n  -- `n` is a normalized absolute path, each of `ps` too (PathsAt): `n` is\n  -- within `p` when it is `p`, or `p` followed by `/`, or `p` is the root.\n  -- The same answer as path_within, by string comparison.\n  pfn any_normal_within(ps : List(String), n : String) : Bool do\n    match ps do\n    Nil -> false\n    Cons(p, rest) ->\n      p == \"/\" || n == p\n        || (string_starts_with(n, p) && string_slice(n, string_byte_length(p), 1) == \"/\")\n        || any_normal_within(rest, n)\n    end\n  end\n\n  -- The target's segments are computed once, not once per scope path.\n  pfn any_within(ps : List(String), p : String) : Bool do\n    any_within_segs(ps, string_starts_with(p, \"/\"), segments(p))\n  end\n\n  pfn any_within_segs(ps : List(String), abs : Bool, segs : List(String)) : Bool do\n    match ps do\n    Nil -> false\n    Cons(s, rest) ->\n      (string_starts_with(s, \"/\") == abs && segs_prefix(segments(s), segs))\n        || any_within_segs(rest, abs, segs)\n    end\n  end\n\n  doc \"\"\"\n  Whether every entry of `a` is covered by some entry of `b`: one whose\n  capability is the same or a lattice ancestor and whose scope contains\n  `a`'s (paths within, names and prefixes subsumed, hosts the same or\n  under the wildcard with path within and methods a subset).\n\n  ## Examples\n\n      march> Authority.subset([Authority.CapEntry(\"IO.FileRead\", Authority.Paths([\"/srv/a\"]))], [Authority.CapEntry(\"IO.FileSystem\", Authority.Paths([\"/srv\"]))])\n      true\n  \"\"\"\n  fn subset(a : List(CapEntry), b : List(CapEntry)) : Bool do\n    match first_outside(a, b) do\n    None -> true\n    Some(_) -> false\n    end\n  end\n\n  pfn covered(s : CapEntry, b : List(CapEntry)) : Bool do\n    match b do\n    Nil -> false\n    Cons(CapEntry(k, outer), rest) ->\n      match s do\n      CapEntry(ik, inner) -> (kind_subsumes(k, ik) && arg_subsumes(outer, inner)) || covered(s, rest)\n      end\n    end\n  end\n\n  pfn arg_subsumes(outer : Arg, inner : Arg) : Bool do\n    match outer do\n    Any -> true\n    Paths(o_paths) ->\n      match path_list(inner) do\n      Some(i_paths) -> all_paths_within(i_paths, o_paths)\n      None -> false\n      end\n    PathsAt(o_paths) ->\n      match path_list(inner) do\n      Some(i_paths) -> all_paths_within(i_paths, o_paths)\n      None -> false\n      end\n    Names(o_names, o_pre) ->\n      match inner do\n      Names(i_names, i_pre) -> all_names_admitted(i_names, o_names, o_pre) && all_prefixes_under(i_pre, o_pre)\n      _ -> false\n      end\n    Hosts(o) ->\n      match host_spec(inner) do\n      Some(i) -> host_subsumes(o, i)\n      None -> false\n      end\n    HostAt(o, _, _, _) ->\n      match host_spec(inner) do\n      Some(i) -> host_subsumes(o, i)\n      None -> false\n      end\n    end\n  end\n\n  -- The paths of a path scope, either form.\n  pfn path_list(a : Arg) : Option(List(String)) do\n    match a do\n    Paths(ps) -> Some(ps)\n    PathsAt(ps) -> Some(ps)\n    _ -> None\n    end\n  end\n\n  -- The packed spec of a host scope, either form.\n  pfn host_spec(a : Arg) : Option(String) do\n    match a do\n    Hosts(s) -> Some(s)\n    HostAt(s, _, _, _) -> Some(s)\n    _ -> None\n    end\n  end\n\n  pfn all_paths_within(i_paths : List(String), o_paths : List(String)) : Bool do\n    match i_paths do\n    Nil -> true\n    Cons(p, rest) -> path_in_any(p, o_paths) && all_paths_within(rest, o_paths)\n    end\n  end\n\n  pfn path_in_any(p : String, o_paths : List(String)) : Bool do\n    match o_paths do\n    Nil -> false\n    Cons(o, rest) -> path_within(o, p) || path_in_any(p, rest)\n    end\n  end\n\n  pfn all_names_admitted(ns : List(String), o_names : List(String), o_pre : List(String)) : Bool do\n    match ns do\n    Nil -> true\n    Cons(n, rest) -> name_admits(o_names, o_pre, n) && all_names_admitted(rest, o_names, o_pre)\n    end\n  end\n\n  pfn all_prefixes_under(i_pre : List(String), o_pre : List(String)) : Bool do\n    match i_pre do\n    Nil -> true\n    Cons(p, rest) -> starts_with_any(p, o_pre) && all_prefixes_under(rest, o_pre)\n    end\n  end\n\n  -- \u2500\u2500 The lattice and which kinds take which scope \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- `kind` and its lattice ancestors, innermost first: `parent` subsumes\n  -- `kind` exactly when it is a member (kind_subsumes).\n  pfn kind_chain(kind : String) : List(String) do\n    let p = lattice_parent(kind)\n    if p == \"\" do Cons(kind, Nil) else Cons(kind, kind_chain(p)) end\n  end\n\n  -- Whether `parent` is `child` or a lattice ancestor of it\n  -- (Cap_lattice.cap_subsumes).\n  pfn kind_subsumes(parent : String, child : String) : Bool do\n    if parent == child do true\n    else do\n      let p = lattice_parent(child)\n      if p == \"\" do false else kind_subsumes(parent, p) end\n    end\n    end\n  end\n\n  -- Cap_scope.is_scopable, split by the kind of scope.\n  pfn path_kind(k : String) : Bool do\n    k == \"IO.FileRead\" || k == \"IO.FileWrite\" || k == \"IO.FileSystem\"\n  end\n\n  pfn host_kind(k : String) : Bool do k == \"IO.NetConnect\" end\n\n  pfn name_kind(k : String) : Bool do k == \"IO.Mut\" || k == \"IO.Registry\" end\n\n  -- BEGIN GENERATED capability lattice: written by lib/caps/emit_march_lattice.ml\n  -- from lib/caps/cap_lattice.ml; do not edit by hand. Regenerate with\n  --   dune build --root . lib/caps/emit_march_lattice.exe\n  --   ./_build/default/lib/caps/emit_march_lattice.exe stdlib/authority.march stdlib/authority.march\n  -- A capability's parent in the lattice, \"\" for a root (and for a\n  -- capability outside the table, such as an FFI root: its own root).\n  pfn lattice_parent(kind : String) : String do\n    match kind do\n    \"IO.Console\" -> \"IO\"\n    \"IO.FileSystem\" -> \"IO\"\n    \"IO.FileRead\" -> \"IO.FileSystem\"\n    \"IO.FileWrite\" -> \"IO.FileSystem\"\n    \"IO.Network\" -> \"IO\"\n    \"IO.NetConnect\" -> \"IO.Network\"\n    \"IO.NetListen\" -> \"IO.Network\"\n    \"IO.Process\" -> \"IO\"\n    \"IO.Clock\" -> \"IO\"\n    \"IO.Random\" -> \"IO\"\n    \"IO.Signal\" -> \"IO\"\n    \"IO.Database\" -> \"IO.NetConnect\"\n    \"IO.Spawn\" -> \"IO\"\n    \"IO.Mut\" -> \"IO\"\n    \"IO.Telemetry\" -> \"IO\"\n    \"IO.NetConnect.TLS\" -> \"IO.NetConnect\"\n    \"IO.WebSocket\" -> \"IO.NetConnect\"\n    \"IO.Foreign\" -> \"IO\"\n    \"IO.Foreign.Blocking\" -> \"IO.Foreign\"\n    \"IO.Registry\" -> \"IO\"\n    \"IO.Cluster\" -> \"IO\"\n    _ -> \"\"\n    end\n  end\n  -- END GENERATED capability lattice\n\n  -- \u2500\u2500 Paths (Cap_scope: lexical, whole segments) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn resolve(cwd : String, p : String) : String do\n    if string_starts_with(p, \"/\") do p else cwd ++ \"/\" ++ p end\n  end\n\n  -- The segments of a path with `.` and empty ones dropped and `..` folded\n  -- away; a `..` at the root is dropped.\n  pfn segments(p : String) : List(String) do\n    rev(fold_segments(string_split(p, \"/\"), Nil), Nil)\n  end\n\n  pfn fold_segments(parts : List(String), acc : List(String)) : List(String) do\n    match parts do\n    Nil -> acc\n    Cons(s, rest) ->\n      if s == \"\" || s == \".\" do fold_segments(rest, acc)\n      else if s == \"..\" do\n        match acc do\n        Nil -> fold_segments(rest, Nil)\n        Cons(_, up) -> fold_segments(rest, up)\n        end\n      else fold_segments(rest, Cons(s, acc)) end end\n    end\n  end\n\n  pfn normalize(p : String) : String do\n    let body = string_join(segments(p), \"/\")\n    if string_starts_with(p, \"/\") do \"/\" ++ body else body end\n  end\n\n  pfn path_within(scope : String, p : String) : Bool do\n    string_starts_with(scope, \"/\") == string_starts_with(p, \"/\")\n      && segs_prefix(segments(scope), segments(p))\n  end\n\n  pfn segs_prefix(pre : List(String), segs : List(String)) : Bool do\n    match pre do\n    Nil -> true\n    Cons(a, pt) ->\n      match segs do\n      Nil -> false\n      Cons(b, st) -> a == b && segs_prefix(pt, st)\n      end\n    end\n  end\n\n  -- \u2500\u2500 Names (Name_scope) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn name_admits(ns : List(String), pre : List(String), n : String) : Bool do\n    member(ns, n) || starts_with_any(n, pre)\n  end\n\n  pfn starts_with_any(n : String, pre : List(String)) : Bool do\n    match pre do\n    Nil -> false\n    Cons(p, rest) -> string_starts_with(n, p) || starts_with_any(n, rest)\n    end\n  end\n\n  -- \u2500\u2500 Hosts (Host_scope) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- A host spec is the scope string the parser packs: `pattern;option;...`\n  -- (`api.x.com/v1/;methods=get`, `;no_redirects`). A pattern is\n  -- (host, wildcard, port or 0, path segments).\n\n  -- Host_scope.permits for one declaration: `target` is `host:port`, split\n  -- at the last `:` (no port, or a bad one, reads as 0).\n  pfn host_permits(spec : String, target : String) : Bool do\n    let raw = spec_pattern(spec)\n    if raw == \"\" do true\n    else\n      match parse_host_pattern(raw) do\n      Err(_) -> false\n      Ok((h, wild, port, _)) ->\n        match split_target(target) do\n        (th, tp) -> host_matches(h, wild, port, th, tp)\n        end\n      end\n    end\n  end\n\n  pfn spec_pattern(spec : String) : String do\n    match string_index_of(spec, \";\") do\n    None -> spec\n    Some(i) -> string_slice(spec, 0, i)\n    end\n  end\n\n  pfn split_target(t : String) : (String, Int) do\n    match string_last_index_of(t, \":\") do\n    None -> (t, 0)\n    Some(i) ->\n      (string_slice(t, 0, i),\n       port_or_zero(string_slice(t, i + 1, string_byte_length(t) - i - 1)))\n    end\n  end\n\n  pfn host_matches(h : String, wild : Bool, port : Int, host : String, tport : Int) : Bool do\n    let th = normalize_host(host)\n    if port != 0 && port != tport do false\n    else if wild do\n      let suffix = \".\" ++ h\n      string_byte_length(th) > string_byte_length(suffix) && string_ends_with(th, suffix)\n    else th == h end end\n  end\n\n  pfn normalize_host(h : String) : String do\n    let l = string_to_lowercase(h)\n    if string_ends_with(l, \".\") do string_slice(l, 0, string_byte_length(l) - 1) else l end\n  end\n\n  -- A port 1-65535 written in at most 5 digits, else 0.\n  pfn port_or_zero(s : String) : Int do\n    if s == \"\" || string_byte_length(s) > 5 || not(all_chars(s, \"0123456789\", 0)) do 0\n    else\n      match string_to_int(s) do\n      Some(n) -> if n >= 1 && n <= 65535 do n else 0 end\n      None -> 0\n      end\n    end\n  end\n\n  pfn all_chars(s : String, allowed : String, i : Int) : Bool do\n    if i >= string_byte_length(s) do true\n    else if string_contains(allowed, string_slice(s, i, 1)) do all_chars(s, allowed, i + 1)\n    else false end end\n  end\n\n  -- Host_scope.parse_pattern.\n  pfn parse_host_pattern(raw : String) : Result((String, Bool, Int, Option(List(String))), String) do\n    if raw == \"\" do Err(\"a host scope cannot be empty\")\n    else if string_contains(raw, \"://\") do\n      Err(\"a host scope names a host, not a URL: drop the scheme (`https://`)\")\n    else\n      let (host_raw, path_r) = match string_index_of(raw, \"/\") do\n        None -> (raw, Ok(None))\n        Some(i) -> (string_slice(raw, 0, i),\n                    parse_scope_path(string_slice(raw, i, string_byte_length(raw) - i)))\n        end\n      match path_r do\n      Err(e) -> Err(e)\n      Ok(path) -> host_part_pattern(string_to_lowercase(host_raw), path)\n      end\n    end end\n  end\n\n  pfn host_part_pattern(s : String, path : Option(List(String))) : Result((String, Bool, Int, Option(List(String))), String) do\n    if s == \"\" do Err(\"a host scope needs a host before its path\")\n    else if string_contains(s, \"@\") do Err(\"a host scope cannot carry userinfo (`user@`)\")\n    else\n      let (host_part, port_text) = split_host_port(s)\n      let port = if port_text == \"\" do 0 else port_or_zero(port_text) end\n      if port_text != \"\" && port == 0 do\n        Err(\"`\" ++ port_text ++ \"` is not a port (1-65535)\")\n      else if string_starts_with(host_part, \"[\") do\n        let n = string_byte_length(host_part)\n        if n >= 2 && string_ends_with(host_part, \"]\")\n           && ipv6_body_ok(string_slice(host_part, 1, n - 2)) do\n          Ok((host_part, false, port, path))\n        else Err(\"`\" ++ host_part ++ \"` is not an IPv6 literal\") end\n      else\n        let wild = string_byte_length(host_part) >= 2 && string_starts_with(host_part, \"*.\")\n        let name = normalize_host(if wild do string_slice(host_part, 2, string_byte_length(host_part) - 2) else host_part end)\n        if string_contains(name, \"*\") || host_part == \"*\" do\n          Err(\"a wildcard must be the whole leftmost label (`*.example.com`)\")\n        else if not(valid_host_name(name)) do\n          Err(\"`\" ++ host_part ++ \"` is not a host name: labels are letters, digits and `-`, separated by single dots\")\n        else Ok((name, wild, port, path)) end end\n      end end\n    end end\n  end\n\n  -- The host and port text of `host[:port]` / `[v6][:port]` (\"\" for none).\n  pfn split_host_port(s : String) : (String, String) do\n    if string_starts_with(s, \"[\") do\n      match string_index_of(s, \"]\") do\n      None -> (s, \"\")\n      Some(i) ->\n        let rest = string_slice(s, i + 1, string_byte_length(s) - i - 1)\n        if rest == \"\" do (string_slice(s, 0, i + 1), \"\")\n        else if string_starts_with(rest, \":\") do\n          (string_slice(s, 0, i + 1), port_text_of(string_slice(rest, 1, string_byte_length(rest) - 1)))\n        else (s, \"\") end end\n      end\n    else\n      match string_last_index_of(s, \":\") do\n      None -> (s, \"\")\n      Some(i) -> (string_slice(s, 0, i), port_text_of(string_slice(s, i + 1, string_byte_length(s) - i - 1)))\n      end\n    end\n  end\n\n  -- An empty port after `:` is still a bad port, not \"no port\".\n  pfn port_text_of(p : String) : String do if p == \"\" do \":\" else p end end\n\n  pfn ipv6_body_ok(b : String) : Bool do\n    b != \"\" && all_chars(b, \"0123456789abcdef:.\", 0)\n  end\n\n  pfn valid_host_name(h : String) : Bool do\n    h != \"\" && labels_ok(string_split(h, \".\"))\n  end\n\n  pfn labels_ok(ls : List(String)) : Bool do\n    match ls do\n    Nil -> true\n    Cons(l, rest) ->\n      l != \"\" && all_chars(l, \"abcdefghijklmnopqrstuvwxyz0123456789-\", 0) && labels_ok(rest)\n    end\n  end\n\n  -- Host_scope.parse_scope_path: `/v1/weather/` as its segments.\n  pfn parse_scope_path(p : String) : Result(Option(List(String)), String) do\n    let parts = drop_last_empty(drop_first(string_split(p, \"/\")))\n    match bad_scope_segment(parts) do\n    None -> Ok(Some(parts))\n    Some(\"\") -> Err(\"a path scope cannot contain `//`\")\n    Some(seg) ->\n      if seg == \".\" || seg == \"..\" do Err(\"a path scope cannot contain a `\" ++ seg ++ \"` segment\")\n      else Err(\"the path segment `\" ++ seg ++ \"` may contain only letters, digits, `-`, `_`, `.` and `~` (no `%`, `?`, `#` or `\\\\`)\") end\n    end\n  end\n\n  pfn drop_first(l : List(String)) : List(String) do\n    match l do\n    Cons(_, rest) -> rest\n    Nil -> Nil\n    end\n  end\n\n  pfn drop_last_empty(l : List(String)) : List(String) do\n    match rev(l, Nil) do\n    Cons(\"\", r) -> rev(r, Nil)\n    _ -> l\n    end\n  end\n\n  pfn bad_scope_segment(segs : List(String)) : Option(String) do\n    match segs do\n    Nil -> None\n    Cons(s, rest) ->\n      if s == \"\" || s == \".\" || s == \"..\"\n         || not(all_chars(s, \"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.~\", 0)) do\n        Some(s)\n      else bad_scope_segment(rest) end\n    end\n  end\n\n  -- Host_scope.parse_decl's options: `no_redirects`, `methods=m,m`.\n  -- (no_redirects, methods given, methods).\n  pfn host_options(opts : List(String), nr : Bool, mg : Bool, ms : List(String)) : Result((Bool, Bool, List(String)), String) do\n    match opts do\n    Nil -> Ok((nr, mg, ms))\n    Cons(o, rest) ->\n      if o == \"no_redirects\" do\n        if nr do Err(\"`no_redirects` is given twice\") else host_options(rest, true, mg, ms) end\n      else if string_starts_with(o, \"methods=\") do\n        if mg do Err(\"`methods(...)` is given twice\")\n        else\n          let v = string_slice(o, 8, string_byte_length(o) - 8)\n          match bad_method(string_split(v, \",\")) do\n          None -> if v == \"\" do Err(\"`methods(...)` needs at least one method\")\n                  else host_options(rest, nr, true, string_split(v, \",\")) end\n          Some(m) -> Err(\"`\" ++ m ++ \"` is not an HTTP method a scope can name; use `get`, `head`, `post`, `put`, `patch`, `delete`, `options`\")\n          end\n        end\n      else Err(\"unknown option `\" ++ o ++ \"`: the options are `no_redirects` and `methods(...)`\") end end\n    end\n  end\n\n  pfn bad_method(ms : List(String)) : Option(String) do\n    match ms do\n    Nil -> None\n    Cons(m, rest) ->\n      if member([\"get\", \"head\", \"post\", \"put\", \"patch\", \"delete\", \"options\"], m) do bad_method(rest)\n      else Some(m) end\n    end\n  end\n\n  -- A host spec as (pattern text, no_redirects, methods given, methods).\n  pfn host_decl(spec : String) : Result((String, Bool, Bool, List(String)), String) do\n    match string_split(spec, \";\") do\n    Nil -> Err(\"a host scope cannot be empty\")\n    Cons(p, opts) ->\n      if p == \"\" && is_nil(opts) do Err(\"a host scope cannot be empty\")\n      else\n        let pat_ok = if p == \"\" do Ok(()) else\n          match parse_host_pattern(p) do\n          Ok(_) -> Ok(())\n          Err(e) -> Err(e)\n          end\n        end\n        match pat_ok do\n        Err(e) -> Err(e)\n        Ok(_) ->\n          match host_options(opts, false, false, Nil) do\n          Err(e) -> Err(e)\n          Ok((nr, mg, ms)) -> Ok((p, nr, mg, ms))\n          end\n        end\n      end\n    end\n  end\n\n  -- Whether host spec `o` permits everything spec `i` does.\n  pfn host_subsumes(o : String, i : String) : Bool do\n    match (host_decl(o), host_decl(i)) do\n    (Ok((o_pre, onr, omg, oms)), Ok((i_pre, inr, img, ims))) ->\n      (not(onr) || inr)\n        && (not(omg) || (img && all_member(ims, oms)))\n        && (o_pre == \"\" || (i_pre != \"\" && pattern_subsumes(o_pre, i_pre)))\n    _ -> false\n    end\n  end\n\n  pfn pattern_subsumes(o : String, i : String) : Bool do\n    match (parse_host_pattern(o), parse_host_pattern(i)) do\n    (Ok((oh, ow, oport, opath)), Ok((ih, iw, iport, ipath))) ->\n      let host_ok = if ow do (iw && ih == oh) || string_ends_with(ih, \".\" ++ oh)\n                    else not(iw) && ih == oh end\n      let port_ok = oport == 0 || oport == iport\n      let path_ok = match opath do\n        None -> true\n        Some(o_paths) ->\n          match ipath do\n          None -> false\n          Some(i_paths) -> segs_prefix(o_paths, i_paths)\n          end\n        end\n      host_ok && port_ok && path_ok\n    _ -> false\n    end\n  end\n\n  -- \u2500\u2500 The scope parser (the `needs` surface grammar) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  --\n  --   list  := \"()\" | entry (\",\" entry)*\n  --   entry := Kind | Kind \"(\" item (\",\" item)* \")\"\n  --   item  := \"string\" | option | option \"(\" \"string\" \")\" | methods \"(\" m (\",\" m)* \")\"\n  --\n  -- A path kind takes paths; IO.NetConnect a host spec packed as the\n  -- compiler's parser packs it (`host/path/;methods=get;no_redirects`); a\n  -- name kind names and `prefix(\"...\")`; any other kind no scope.\n\n  doc \"\"\"\n  Parses a scope list written as a `needs` clause (`IO.Console,\n  IO.FileRead(\"/srv/\")`; `()` is the empty list) into scopes, or the reason\n  it is not one.\n\n  ## Examples\n\n      march> Authority.parse(\"()\")\n      Ok([])\n  \"\"\"\n  fn parse(text : String) : Result(List(CapEntry), String) do\n    match tokenize(text, 0, string_byte_length(text), Nil) do\n    Err(e) -> Err(e)\n    Ok(toks) ->\n      match toks do\n      Nil -> Ok(Nil)\n      Cons(\"(\", Cons(\")\", Nil)) -> Ok(Nil)\n      _ -> parse_entries(toks, Nil)\n      end\n    end\n  end\n\n  -- Tokens: \"(\", \")\", \",\", a word (letters, digits, `_`, `.`), and a\n  -- string, kept as `\"` followed by its decoded contents.\n  pfn tokenize(s : String, i : Int, n : Int, acc : List(String)) : Result(List(String), String) do\n    if i >= n do Ok(rev(acc, Nil))\n    else do\n      let c = string_slice(s, i, 1)\n      if c == \" \" || c == \"\\t\" || c == \"\\n\" || c == \"\\r\" do tokenize(s, i + 1, n, acc)\n      else if c == \"(\" || c == \")\" || c == \",\" do tokenize(s, i + 1, n, Cons(c, acc))\n      else if c == \"\\\"\" do\n        match read_string(s, i + 1, n, \"\") do\n        Err(e) -> Err(e)\n        Ok((str, j)) -> tokenize(s, j, n, Cons(\"\\\"\" ++ str, acc))\n        end\n      else if is_word_char(c) do\n        let j = word_end(s, i, n)\n        tokenize(s, j, n, Cons(string_slice(s, i, j - i), acc))\n      else Err(\"unexpected `\" ++ c ++ \"`\") end end end end\n    end\n    end\n  end\n\n  pfn is_word_char(c : String) : Bool do\n    c != \"\" && string_contains(\"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.\", c)\n  end\n\n  pfn word_end(s : String, i : Int, n : Int) : Int do\n    if i < n && is_word_char(string_slice(s, i, 1)) do word_end(s, i + 1, n) else i end\n  end\n\n  pfn read_string(s : String, i : Int, n : Int, acc : String) : Result((String, Int), String) do\n    if i >= n do Err(\"a string is not closed\")\n    else do\n      let c = string_slice(s, i, 1)\n      if c == \"\\\"\" do Ok((acc, i + 1))\n      else if c == \"\\\\\" do\n        if i + 1 >= n do Err(\"a string is not closed\")\n        else do\n          let e = string_slice(s, i + 1, 1)\n          let d = if e == \"n\" do \"\\n\" else if e == \"t\" do \"\\t\" else if e == \"r\" do \"\\r\" else e end end end\n          read_string(s, i + 2, n, acc ++ d)\n        end\n        end\n      else read_string(s, i + 1, n, acc ++ c) end end\n    end\n    end\n  end\n\n  pfn is_string_tok(t : String) : Bool do string_starts_with(t, \"\\\"\") end\n\n  pfn string_tok_text(t : String) : String do string_slice(t, 1, string_byte_length(t) - 1) end\n\n  pfn describe_tok(t : String) : String do\n    if is_string_tok(t) do \"a string\" else \"`\" ++ t ++ \"`\" end\n  end\n\n  pfn parse_entries(toks : List(String), acc : List(CapEntry)) : Result(List(CapEntry), String) do\n    match parse_entry(toks) do\n    Err(e) -> Err(e)\n    Ok((scope, rest)) ->\n      match rest do\n      Nil -> Ok(rev_scopes(Cons(scope, acc), Nil))\n      Cons(\",\", more) -> parse_entries(more, Cons(scope, acc))\n      Cons(t, _) -> Err(\"expected `,` between capabilities, found \" ++ describe_tok(t))\n      end\n    end\n  end\n\n  pfn parse_entry(toks : List(String)) : Result((CapEntry, List(String)), String) do\n    match toks do\n    Nil -> Err(\"expected a capability at the end\")\n    Cons(k, rest) ->\n      if not(is_kind(k)) do Err(\"expected a capability such as `IO.Console`, found \" ++ describe_tok(k))\n      else\n        match rest do\n        Cons(\"(\", after) ->\n          match after do\n          Cons(\")\", _) -> Err(\"`\" ++ k ++ \"()` names no scope: write `\" ++ k ++ \"` for any target\")\n          _ ->\n            match parse_items(after, Nil, Nil) do\n            Err(e) -> Err(e)\n            Ok((strs, opts, more)) ->\n              match scope_arg(k, strs, opts) do\n              Err(e) -> Err(e)\n              Ok(arg) -> Ok((CapEntry(k, arg), more))\n              end\n            end\n          end\n        _ -> Ok((CapEntry(k, Any), rest))\n        end\n      end\n    end\n  end\n\n  -- Dot-separated names, each starting with an upper-case letter.\n  pfn is_kind(w : String) : Bool do\n    not(is_string_tok(w)) && w != \"(\" && w != \")\" && w != \",\" && kind_parts_ok(string_split(w, \".\"))\n  end\n\n  pfn kind_parts_ok(ps : List(String)) : Bool do\n    match ps do\n    Nil -> true\n    Cons(p, rest) ->\n      p != \"\" && string_contains(\"ABCDEFGHIJKLMNOPQRSTUVWXYZ\", string_slice(p, 0, 1)) && kind_parts_ok(rest)\n    end\n  end\n\n  pfn is_option_name(w : String) : Bool do\n    w != \"\" && all_chars(w, \"abcdefghijklmnopqrstuvwxyz_\", 0)\n  end\n\n  -- The items of a scope up to its `)`: strings (rev), options (rev) as\n  -- `name`, `name=value` or `methods=a,b`, and the tokens after the `)`.\n  pfn parse_items(toks : List(String), strs : List(String), opts : List(String)) : Result((List(String), List(String), List(String)), String) do\n    match toks do\n    Nil -> Err(\"a scope is not closed: expected `)`\")\n    Cons(t, rest) ->\n      let item = if is_string_tok(t) do\n        if is_nil(opts) do Ok((Cons(string_tok_text(t), strs), opts, rest))\n        else Err(\"a string cannot follow an option in a scope\") end\n      else if is_option_name(t) do\n        match parse_option(t, rest) do\n        Err(e) -> Err(e)\n        Ok((o, more)) -> Ok((strs, Cons(o, opts), more))\n        end\n      else Err(\"expected a string or an option in a scope, found \" ++ describe_tok(t)) end end\n      match item do\n      Err(e) -> Err(e)\n      Ok((s2, o2, more)) ->\n        match more do\n        Cons(\")\", after) -> Ok((rev(s2, Nil), rev(o2, Nil), after))\n        Cons(\",\", after) -> parse_items(after, s2, o2)\n        Cons(x, _) -> Err(\"expected `,` or `)` in a scope, found \" ++ describe_tok(x))\n        Nil -> Err(\"a scope is not closed: expected `)`\")\n        end\n      end\n    end\n  end\n\n  -- `name`, `name(\"value\")` as `name=value`, `methods(a, b)` as `methods=a,b`.\n  pfn parse_option(name : String, toks : List(String)) : Result((String, List(String)), String) do\n    match toks do\n    Cons(\"(\", Cons(v, Cons(\")\", rest))) ->\n      if is_string_tok(v) do\n        if name == \"methods\" do Err(\"`methods(...)` takes HTTP method names, not a string\")\n        else Ok((name ++ \"=\" ++ string_tok_text(v), rest)) end\n      else if name == \"methods\" && is_option_name(v) do Ok((\"methods=\" ++ v, rest))\n      else Err(\"`\" ++ name ++ \"(...)` takes a quoted string\") end end\n    Cons(\"(\", more) ->\n      if name == \"methods\" do\n        match method_words(more, Nil) do\n        Err(e) -> Err(e)\n        Ok((ms, rest)) -> Ok((\"methods=\" ++ string_join(ms, \",\"), rest))\n        end\n      else Err(\"`\" ++ name ++ \"(...)` takes one quoted string\") end\n    _ -> Ok((name, toks))\n    end\n  end\n\n  pfn method_words(toks : List(String), acc : List(String)) : Result((List(String), List(String)), String) do\n    match toks do\n    Cons(m, Cons(\",\", rest)) ->\n      if is_option_name(m) do method_words(rest, Cons(m, acc))\n      else Err(\"`methods(...)` takes HTTP method names\") end\n    Cons(m, Cons(\")\", rest)) ->\n      if is_option_name(m) do Ok((rev(Cons(m, acc), Nil), rest))\n      else Err(\"`methods(...)` takes HTTP method names\") end\n    _ -> Err(\"`methods(...)` is not closed\")\n    end\n  end\n\n  pfn scope_arg(k : String, strs : List(String), opts : List(String)) : Result(Arg, String) do\n    if path_kind(k) do\n      if not(is_nil(opts)) do Err(\"a path scope on `\" ++ k ++ \"` takes only paths\")\n      else if member(strs, \"\") do Err(\"a path scope cannot be empty\")\n      else match first_relative(strs) do\n        Some(p) -> Err(\"the scope `\" ++ p ++ \"` on `\" ++ k ++ \"` is a relative path; give an absolute path, one starting with `/`\")\n        None -> Ok(PathsAt(map_normalize(strs)))\n        end\n      end end\n    else if host_kind(k) do\n      let spec = match strs do\n        Nil -> \";\" ++ string_join(opts, \";\")\n        Cons(first, more) -> string_join(Cons(first, append(prefix_all(more, \"name=\"), opts)), \";\")\n        end\n      match host_decl(spec) do\n      Err(e) -> Err(e)\n      Ok((p, _, _, _)) ->\n        if p == \"\" do Ok(HostAt(spec, \"\", false, 0))\n        else\n          match parse_host_pattern(p) do\n          Ok((h, wild, port, _)) -> Ok(HostAt(spec, h, wild, port))\n          Err(e) -> Err(e)\n          end\n        end\n      end\n    else if name_kind(k) do\n      match name_options(opts, Nil) do\n      Err(e) -> Err(e)\n      Ok(prefixes) ->\n        match bad_name_text(strs, \"a name\") do\n        Some(e) -> Err(e)\n        None ->\n          match bad_name_text(prefixes, \"a prefix\") do\n          Some(e) -> Err(e)\n          None -> Ok(Names(strs, prefixes))\n          end\n        end\n      end\n    else Err(\"`\" ++ k ++ \"` takes no scope\") end end end\n  end\n\n  pfn first_relative(ps : List(String)) : Option(String) do\n    match ps do\n    Nil -> None\n    Cons(p, rest) -> if string_starts_with(p, \"/\") do first_relative(rest) else Some(p) end\n    end\n  end\n\n  pfn name_options(opts : List(String), acc : List(String)) : Result(List(String), String) do\n    match opts do\n    Nil -> Ok(rev(acc, Nil))\n    Cons(o, rest) ->\n      if string_starts_with(o, \"prefix=\") do\n        name_options(rest, Cons(string_slice(o, 7, string_byte_length(o) - 7), acc))\n      else Err(\"`\" ++ o ++ \"` is not an option a name scope takes; it takes names and `prefix(\\\"...\\\")`\") end\n    end\n  end\n\n  -- Name_scope.check_text: not empty, and no `;`, `=` or `,`.\n  pfn bad_name_text(ns : List(String), what : String) : Option(String) do\n    match ns do\n    Nil -> None\n    Cons(n, rest) ->\n      if n == \"\" do Some(what ++ \" cannot be empty\")\n      else if string_contains(n, \";\") || string_contains(n, \"=\") || string_contains(n, \",\") do\n        Some(what ++ \" `\" ++ n ++ \"` contains `;`, `=` or `,`\")\n      else bad_name_text(rest, what) end end\n    end\n  end\n\n  -- \u2500\u2500 Writing a scope back as text (for launch errors) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  pfn scope_text(s : CapEntry) : String do\n    match s do\n    CapEntry(k, Any) -> k\n    CapEntry(k, Paths(ps)) -> k ++ \"(\" ++ string_join(quote_all(ps), \", \") ++ \")\"\n    CapEntry(k, PathsAt(ps)) -> k ++ \"(\" ++ string_join(quote_all(ps), \", \") ++ \")\"\n    CapEntry(k, Names(ns, pre)) ->\n      k ++ \"(\" ++ string_join(append(quote_all(ns), wrap_all(quote_all(pre), \"prefix(\")), \", \") ++ \")\"\n    CapEntry(k, Hosts(spec)) -> host_scope_text(k, spec)\n    CapEntry(k, HostAt(spec, _, _, _)) -> host_scope_text(k, spec)\n    end\n  end\n\n  pfn host_scope_text(k : String, spec : String) : String do\n    match string_split(spec, \";\") do\n    Nil -> k\n    Cons(first, opts) ->\n      let head = if first == \"\" do Nil else Cons(quote(first), Nil) end\n      k ++ \"(\" ++ string_join(append(head, option_texts(opts)), \", \") ++ \")\"\n    end\n  end\n\n  pfn option_texts(opts : List(String)) : List(String) do\n    match opts do\n    Nil -> Nil\n    Cons(o, rest) ->\n      let t = match string_index_of(o, \"=\") do\n        None -> o\n        Some(i) ->\n          let name = string_slice(o, 0, i)\n          let v = string_slice(o, i + 1, string_byte_length(o) - i - 1)\n          if name == \"name\" do quote(v)\n          else if name == \"methods\" do \"methods(\" ++ string_join(string_split(v, \",\"), \", \") ++ \")\"\n          else name ++ \"(\" ++ quote(v) ++ \")\" end end\n        end\n      Cons(t, option_texts(rest))\n    end\n  end\n\n  pfn quote(s : String) : String do\n    \"\\\"\" ++ string_replace_all(string_replace_all(s, \"\\\\\", \"\\\\\\\\\"), \"\\\"\", \"\\\\\\\"\") ++ \"\\\"\"\n  end\n\n  pfn quote_all(l : List(String)) : List(String) do\n    match l do\n    Nil -> Nil\n    Cons(x, rest) -> Cons(quote(x), quote_all(rest))\n    end\n  end\n\n  pfn wrap_all(l : List(String), pre : String) : List(String) do\n    match l do\n    Nil -> Nil\n    Cons(x, rest) -> Cons(pre ++ x ++ \")\", wrap_all(rest, pre))\n    end\n  end\n\n  -- \u2500\u2500 List helpers (Authority loads before List) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n  -- Monomorphic on purpose: a named type variable on a stdlib helper here\n  -- survives monomorphisation (the TIR verifier rejects it).\n  pfn rev(l : List(String), acc : List(String)) : List(String) do\n    match l do\n    Nil -> acc\n    Cons(x, rest) -> rev(rest, Cons(x, acc))\n    end\n  end\n\n  pfn rev_scopes(l : List(CapEntry), acc : List(CapEntry)) : List(CapEntry) do\n    match l do\n    Nil -> acc\n    Cons(x, rest) -> rev_scopes(rest, Cons(x, acc))\n    end\n  end\n\n  pfn append(a : List(String), b : List(String)) : List(String) do rev(rev(a, Nil), b) end\n\n  -- By match, not `==`: List's Eq is not in scope everywhere Authority loads.\n  pfn is_nil(l : List(String)) : Bool do\n    match l do\n    Nil -> true\n    _ -> false\n    end\n  end\n\n  pfn member(l : List(String), x : String) : Bool do\n    match l do\n    Nil -> false\n    Cons(y, rest) -> y == x || member(rest, x)\n    end\n  end\n\n  pfn all_member(xs : List(String), l : List(String)) : Bool do\n    match xs do\n    Nil -> true\n    Cons(x, rest) -> member(l, x) && all_member(rest, l)\n    end\n  end\n\n  pfn prefix_all(l : List(String), pre : String) : List(String) do\n    match l do\n    Nil -> Nil\n    Cons(x, rest) -> Cons(pre ++ x, prefix_all(rest, pre))\n    end\n  end\n\n  pfn map_normalize(l : List(String)) : List(String) do\n    match l do\n    Nil -> Nil\n    Cons(x, rest) -> Cons(normalize(x), map_normalize(rest))\n    end\n  end\n\n  doc \"\"\"\n  The layer of a `restrict` block at `where` (`<file>:<line>`), whose scope\n  list is `text`: the text parsed into scopes. The compiler calls it once per\n  literal site (`restrict_layer` cell) and the interpreter per entry. A scope\n  that is not a scope list cannot reach here: it was validated at compile time\n  or by `Scope.build`.\n  \"\"\"\n  @[stdlib_internal]\n  fn restrict_layer(where : String, text : String) : Layer do\n    match parse(text) do\n    Ok(scopes) -> Layer(ByRestrict(where), text, scopes)\n    Err(e) -> panic(\"internal: the restrict at \" ++ where ++ \" is not a scope list: \" ++ e)\n    end\n  end\n\n  -- \u2500\u2500 Dependency grants (ocap phase 6) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- (at the end of the module, so no existing line moves: panic sites\n  -- carry line numbers)\n\n  doc \"\"\"\n  The layer of the grant to dependency package `pkg`, whose grant (as the\n  consumer's `forge.toml` writes it, in `needs` syntax) is `text`: the text\n  parsed into scopes. The compiler validated the text, so a parse failure\n  is an internal error.\n\n  ## Examples\n\n      march> Authority.grant_layer(\"weather\", \"IO.Console\")\n      Layer(ByGrant(\"weather\"), \"IO.Console\", [CapEntry(\"IO.Console\", Any)])\n  \"\"\"\n  fn grant_layer(pkg : String, text : String) : Layer do\n    match parse(text) do\n    Ok(scopes) -> Layer(ByGrant(pkg), text, scopes)\n    Err(e) -> panic(\"internal: the grant to package \" ++ pkg ++ \" is not a scope list: \" ++ e)\n    end\n  end\n\n  doc \"\"\"\n  Enters a dependency grant's frame (`layer`, from `grant_layer`) and\n  returns the authority to restore on leaving it. Unlike `enter_fn`, the\n  layer is not pushed when the same grant (the same limit and scope text)\n  is anywhere in the current list, not only on top: intersection is\n  idempotent, so the answer is the same, and recursion in and out of a\n  granted package (which interleaves function frames) keeps the list from\n  growing.\n  \"\"\"\n  @[stdlib_internal]\n  -- The result is a CapAuthRef, as for `enter_fn`.\n  fn enter_grant(layer : Layer) do\n    if has_layer(cap_layers(), layer) do cap_save()\n    else cap_push(layer) end\n  end\n\n  doc \"\"\"\n  Whether `layers` holds a layer with the same limit and scope text as\n  `layer` (its parsed scopes are not compared: the text determines them).\n\n  ## Examples\n\n      march> Authority.has_layer([Authority.grant_layer(\"weather\", \"IO.Console\")], Authority.grant_layer(\"weather\", \"IO.Console\"))\n      true\n      march> Authority.has_layer([Authority.frame_layer(\"f\", \"IO.Console\")], Authority.grant_layer(\"weather\", \"IO.Console\"))\n      false\n  \"\"\"\n  fn has_layer(layers : List(Layer), layer : Layer) : Bool do\n    match layers do\n    Nil -> false\n    Cons(Layer(l, t, _), rest) ->\n      match layer do\n      Layer(limit, text, _) -> if l == limit && t == text do true else has_layer(rest, layer) end\n      end\n    end\n  end\n\n  doc \"\"\"\n  Refuses a call of C code (an `extern`) made under a dependency grant\n  that does not admit `IO.Foreign`: panics with `describe` of the refusal\n  (an extern returns a plain value, so its refusal cannot be an `Err`).\n  Only a grant's layer refuses: a function's `needs`, a `restrict` and the\n  launch grant leave externs to the static checks, as before. The compiler\n  puts a call of this in front of every extern call of a program built under\n  grants (lib/tir/auth_rt.ml, `grants`); the interpreter calls it before an\n  extern once a grant frame exists.\n  \"\"\"\n  @[stdlib_internal]\n  fn foreign_guard() : () do\n    if cap_check_raw(\"IO.Foreign\", \"\") == 0 do ()\n    else\n      match grant_refusal(cap_layers()) do\n      None -> ()\n      Some(e) -> panic(\"capability refused: \" ++ describe(e))\n      end\n    end\n  end\n\n  -- The innermost grant layer that does not admit `IO.Foreign`.\n  pfn grant_refusal(layers : List(Layer)) : Option(CapError) do\n    match layers do\n    Nil -> None\n    Cons(Layer(ByGrant(p), text, scopes), rest) ->\n      if admits(scopes, \"IO.Foreign\", \"\", \"/\") do grant_refusal(rest)\n      else Some(CapError(\"IO.Foreign\", \"\", ByGrant(p), text)) end\n    Cons(_, rest) -> grant_refusal(rest)\n    end\n  end\n\n  -- \u2500\u2500 Mocks (ocap phase 7) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n  -- `mock SCOPE with HANDLER do ... end` (test builds only) pushes a layer\n  -- `Layer(ByMock(id), text, scopes)`; `id` names the handler record in the\n  -- runtime's mock registry (`mock_register` / `mock_lookup`). Being a layer\n  -- of the current authority, it travels with every closure, task and actor\n  -- made inside the block. A mock covers an operation when one of its scope\n  -- entries is of exactly the operation's kind (a handler is per kind, so the\n  -- lattice is not consulted) and admits the target.\n\n  doc \"\"\"\n  The layer of a mock whose handler is registered as `id` and whose scope\n  list is `text`. The compiler validated the text, so a parse failure is an\n  internal error.\n\n  ## Examples\n\n      march> Authority.mock_layer(0, \"IO.Console\")\n      Layer(ByMock(0), \"IO.Console\", [CapEntry(\"IO.Console\", Any)])\n  \"\"\"\n  @[stdlib_internal]\n  fn mock_layer(id : Int, text : String) : Layer do\n    match parse(text) do\n    Ok(scopes) -> Layer(ByMock(id), text, scopes)\n    Err(e) -> panic(\"internal: a mock scope is not a scope list: \" ++ e)\n    end\n  end\n\n  doc \"\"\"\n  The registry id of the innermost mock in force that covers an operation\n  of capability `kind` on `target`, if any. A mock under a `restrict` or a\n  function frame that does not admit the operation is not found: those\n  limits bind a test too. What a test build's dispatch wrapper asks before\n  each interceptable operation.\n  \"\"\"\n  @[stdlib_internal]\n  fn mock_for(kind : String, target : String) : Option(Int) do\n    match cap_layers() do\n    Nil -> None\n    layers ->\n      let cwd = if path_kind(kind) && not(string_starts_with(target, \"/\")) do cap_cwd() else \"/\" end\n      mock_in(kind, kind_chain(kind), target, cwd, layers)\n    end\n  end\n\n  pfn mock_in(kind : String, chain : List(String), target : String, cwd : String, layers : List(Layer)) : Option(Int) do\n    match layers do\n    Nil -> None\n    Cons(Layer(ByMock(id), _, scopes), rest) ->\n      if mock_covers(scopes, kind, target, cwd) do Some(id) else mock_in(kind, chain, target, cwd, rest) end\n    Cons(Layer(_, _, scopes), rest) ->\n      if admits_in(scopes, chain, kind, target, cwd) do mock_in(kind, chain, target, cwd, rest) else None end\n    end\n  end\n\n  pfn mock_covers(scopes : List(CapEntry), kind : String, target : String, cwd : String) : Bool do\n    match scopes do\n    Nil -> false\n    Cons(CapEntry(k, arg), rest) ->\n      (k == kind && arg_admits(arg, kind, target, cwd)) || mock_covers(rest, kind, target, cwd)\n    end\n  end\n\n  doc \"\"\"\n  `check` as if no mock were in force: the layers with every mock layer\n  removed. A test build's dispatch wrapper calls it before running the real\n  operation for one its mock's handler leaves alone (`None`), so a mock\n  never lets a test reach the outside world beyond its launch.\n\n  ## Examples\n\n      march> Authority.check_unmocked(\"IO.Console\", \"stdout\")\n      Ok(())\n  \"\"\"\n  fn check_unmocked(kind : String, target : String) : Result((), CapError) do\n    check_layers(kind, target, drop_mocks(cap_layers()))\n  end\n\n  pfn drop_mocks(layers : List(Layer)) : List(Layer) do\n    match layers do\n    Nil -> Nil\n    Cons(Layer(ByMock(_), _, _), rest) -> drop_mocks(rest)\n    Cons(l, rest) -> Cons(l, drop_mocks(rest))\n    end\n  end\n\n  doc \"\"\"\n  What a dispatch wrapper calls before the real operation when the mock\n  covering it has no handler for that operation: nothing when the authority\n  outside the mock admits it, else a panic naming the refusal (the\n  operation's own result type cannot carry it; a test build only).\n  \"\"\"\n  @[stdlib_internal]\n  fn mock_fallthrough(kind : String, target : String) : () do\n    match check_unmocked(kind, target) do\n    Ok(_) -> ()\n    Err(e) -> panic(\"capability refused: \" ++ describe(e) ++ \" (the mock in force does not handle this operation)\")\n    end\n  end\n\n  doc \"\"\"\n  Whether a frame with the limit and scope text of `layer` is anywhere in\n  the authority in force, not only on top. Entering such a frame again\n  would add nothing (the authority is the intersection of its layers), so\n  a tail call between two framed functions goes straight to the callee's\n  body when its frame is in force, and a mutual recursion through framed\n  functions loops instead of growing the stack (Auth_rt.frames).\n  \"\"\"\n  @[stdlib_internal]\n  fn frame_in_force(layer : Layer) : Bool do\n    match layer do\n    Layer(limit, text, _) -> layer_in(cap_layers(), limit, text)\n    end\n  end\n\n  pfn layer_in(layers : List(Layer), limit : CapLimit, text : String) : Bool do\n    match layers do\n    Nil -> false\n    Cons(Layer(l, t, _), rest) -> if l == limit && t == text do true else layer_in(rest, limit, text) end\n    end\n  end\n\nend\n";
